                    position.set(Position.KEY_POWER, Double.parseDouble(value));
                    break;
                case "backup_voltage":
                    position.set(Position.KEY_BATTERY, Double.parseDouble(value));
                    break;
                case "analog1":
                case "analog2":
                case "analog3":
                    position.set(Position.PREFIX_ADC + (key.charAt(key.length() - 1) - '0'), Double.parseDouble(value));
                    break;
                case "extra1":
                case "extra2":
                case "extra3":
